import React from 'react';
import { Users, AlertTriangle, FileText, Shield } from 'lucide-react';

const DashboardSummary = ({ breachEvents, tamperingResults, isLoading }) => {
  const calculateStats = () => {
    if (!breachEvents || !tamperingResults) return { totalLogins: 0, totalAnomalies: 0, totalTampered: 0 };
    
    const totalLogins = breachEvents.length;
    const totalAnomalies = breachEvents.filter(event => event.is_anomalous).length;
    const totalTampered = tamperingResults.filter(file => file.status === 'tampered').length;
    
    return { totalLogins, totalAnomalies, totalTampered };
  };

  const stats = calculateStats();

  const summaryCards = [
    {
      title: 'Total Logins Processed',
      value: stats.totalLogins,
      icon: Users,
      color: 'bg-blue-500',
      bgColor: 'bg-blue-50',
      textColor: 'text-blue-700',
      borderColor: 'border-blue-200'
    },
    {
      title: 'Anomalies Detected',
      value: stats.totalAnomalies,
      icon: AlertTriangle,
      color: 'bg-red-500',
      bgColor: 'bg-red-50',
      textColor: 'text-red-700',
      borderColor: 'border-red-200'
    },
    {
      title: 'Tampered Files',
      value: stats.totalTampered,
      icon: FileText,
      color: 'bg-orange-500',
      bgColor: 'bg-orange-50',
      textColor: 'text-orange-700',
      borderColor: 'border-orange-200'
    }
  ];

  if (isLoading) {
    return (
      <div className="grid grid-cols-3 gap-4 mb-6">
        {[1, 2, 3].map((i) => (
          <div key={i} className="card" style={{ minHeight: '120px' }}>
            <div className="loading" style={{ margin: '0 auto' }}></div>
            <p style={{ textAlign: 'center', marginTop: '1rem', color: '#6b7280' }}>Loading...</p>
          </div>
        ))}
      </div>
    );
  }

  return (
    <div className="grid grid-cols-3 gap-4 mb-6">
      {summaryCards.map((card, index) => (
        <div key={index} className="summary-card">
          <div className="summary-card-content">
            <div className="summary-icon">
              <card.icon size={24} />
            </div>
            <div className="summary-text">
              <h3 className="summary-title">{card.title}</h3>
              <p className="summary-value">{card.value.toLocaleString()}</p>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
};

export default DashboardSummary;
